<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useRoute } from 'vue-router';
import StorefrontNav from '@/components/StorefrontNav.vue';
import { sampleGemProducts } from '@/data/catalog';
import { isBackendConfigured } from '@/lib/supabase';
import { listProducts, type StoreProduct } from '@/services/products';
const route=useRoute(); const product=ref<StoreProduct|null>(null); const loading=ref(true); const error=ref('');
const price=computed(()=>product.value ? (isBackendConfigured ? new Intl.NumberFormat('en-LK',{style:'currency',currency:'LKR',maximumFractionDigits:0}).format(product.value.price_lkr) : 'Price by enquiry'):'');
onMounted(async()=>{try{const products=isBackendConfigured?await listProducts():sampleGemProducts.map((p,i)=>({id:String(p.id),slug:`evoryn-selection-${i+1}`,name:p.title,description:'A considered selection from Evoryn’s Ceylon collection. Contact our team for stone details and provenance.',category:p.category,price_lkr:Math.round(p.price*300),price_usd:p.price,stock_quantity:p.stock,image_url:p.thumbnail,is_published:true})) as StoreProduct[]; product.value=products.find(p=>p.slug===route.params.slug)||null;}catch(e){error.value=e instanceof Error?e.message:'Could not load this piece.'}finally{loading.value=false}});
</script>
<template><main class="detail-page"><StorefrontNav/><div class="detail-wrap"><RouterLink to="/shop" class="back-link">← BACK TO THE COLLECTION</RouterLink><p v-if="loading" class="message">Opening this piece…</p><p v-else-if="error" class="message">{{error}}</p><p v-else-if="!product" class="message">This piece is not currently available. <RouterLink to="/shop">Browse the collection</RouterLink></p><section v-else class="detail-grid"><div class="detail-image"><img :src="product.image_url" :alt="product.name"/></div><div class="detail-copy"><p class="eyebrow">{{product.category==='gemstone'?'CEYLON GEMSTONE':'EVORYN FINE JEWELLERY'}}</p><h1>{{product.name}}</h1><p class="detail-price">{{price}} <small>/ {{product.price_usd.toLocaleString('en-US',{style:'currency',currency:'USD'})}}</small></p><div class="gold-rule"></div><p class="description">{{product.description}}</p><p class="inventory">{{product.stock_quantity>0?'Available for a personal enquiry':'Made available by enquiry'}}</p><a class="enquire" href="mailto:care@evoryn.lk?subject=Enquiry%20about%20an%20Evoryn%20piece">ENQUIRE ABOUT THIS PIECE <span>↗</span></a><p class="note">A member of our team can help with stone details, shipping and care. Orders are confirmed directly with Evoryn.</p></div></section></div></main></template>
<style scoped>
.detail-page{min-height:100vh;background:#10100f;color:#f3efe7}.detail-wrap{max-width:1340px;margin:auto;padding:35px clamp(22px,8vw,120px) 100px}.back-link{color:#c7a35f;font:9px Arial,sans-serif;text-decoration:none;letter-spacing:.16em}.detail-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:clamp(36px,8vw,110px);align-items:center;padding-top:50px}.detail-image{height:min(68vh,660px);background:#171716}.detail-image img{width:100%;height:100%;object-fit:cover;mix-blend-mode:screen}.eyebrow{font:9px Arial,sans-serif;letter-spacing:.18em;color:#c7a35f}.detail-copy h1{font:400 clamp(38px,5vw,65px)/1.05 Georgia,serif;margin:20px 0}.detail-price{font:18px Georgia,serif;color:#e4c782}.detail-price small{font:11px Arial,sans-serif;color:#a7a093}.gold-rule{width:52px;height:1px;background:#c7a35f;margin:29px 0}.description,.note{color:#b9b2a5;font:15px/1.8 Georgia,serif}.inventory{margin-top:25px;color:#d9d1c2;font:10px Arial,sans-serif;letter-spacing:.1em;text-transform:uppercase}.enquire{display:flex;justify-content:space-between;align-items:center;margin-top:28px;background:#d6b56f;color:#13120f;text-decoration:none;padding:17px 20px;font:10px Arial,sans-serif;letter-spacing:.15em}.note{font-size:12px;margin-top:18px}.message{padding:90px 0;text-align:center;color:#c7c0b2}@media(max-width:760px){.detail-grid{grid-template-columns:1fr;padding-top:30px}.detail-image{height:390px}.detail-copy h1{font-size:43px}}
</style>
